// src/RoleSelection.js
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "./auth";

export default function RoleSelection() {
  const [role, setRole] = useState("");
  const [customPurpose, setCustomPurpose] = useState("");
  const { setUserRole } = useAuth(); // Assuming your auth context supports this
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!role) {
      alert("Please select a role!");
      return;
    }

    // Save role in auth context or localStorage
    setUserRole(role);

    // Redirect based on role
    if (role === "student") {
      navigate("/dashboard");
    } else if (role === "teacher") {
      navigate("/dashboard"); // Replace with teacher dashboard if exists
    } else if (role === "custom") {
      if (!customPurpose.trim()) {
        alert("Please enter a custom purpose!");
        return;
      }
      navigate("/dashboard"); // Or handle custom logic
    }
  };

  return (
    <div className="max-w-md mx-auto bg-white shadow p-6 rounded-lg">
      <h2 className="text-2xl font-bold text-center mb-4">Select Your Role</h2>
      <form onSubmit={handleSubmit} className="flex flex-col gap-4">
        <select
          value={role}
          onChange={(e) => setRole(e.target.value)}
          className="border p-2 rounded"
          required
        >
          <option value="">-- Select Role --</option>
          <option value="student">Student</option>
          <option value="teacher">Teacher</option>
          <option value="custom">Custom</option>
        </select>

        {role === "custom" && (
          <input
            type="text"
            placeholder="Enter custom purpose"
            value={customPurpose}
            onChange={(e) => setCustomPurpose(e.target.value)}
            className="border p-2 rounded"
            required
          />
        )}

        <button
          type="submit"
          className="bg-indigo-600 text-white px-4 py-2 rounded hover:bg-indigo-500"
        >
          Continue
        </button>
      </form>
    </div>
  );
}
